`timescale 1ns/1ps
// Runtime-writable phase step; every sample is generated by FPGA logic.
// Pitch changes preserve phase. Phase keeps running while the output is muted.
module dds_voice (
    input wire clk,
    input wire resetn,
    input wire sample_ce,
    input wire [31:0] phase_inc,
    output wire signed [15:0] sample
);
    reg [31:0] phase;
    always @(posedge clk) begin
        if (!resetn)
            phase <= 32'd0;
        else if (sample_ce)
            phase <= phase + phase_inc;
    end
    sine_rom u_sine (.address(phase[31:22]), .sample(sample));
endmodule
